window.HOEREN_TESTS[94] = {"id":"beim-tierfriseur","name":"Beim Tierfriseur","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist der Hundesalon Schöner Hund. Ihr Termin für Ihren Hund ist morgen. Aber nicht um 14 Uhr, sondern schon um 11 Uhr. Bringen Sie den Hund bitte ohne Futter, er soll vorher nicht fressen. Die ganze Behandlung dauert etwa zwei Stunden. Bis morgen, auf Wiederhören!","gender":"f","q":"Wann ist der Termin?","opts":["Um 16 Uhr.","Um 14 Uhr.","Um 11 Uhr."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Mein Hund haart so stark, das ganze Sofa ist voll! Ich war beim Tierfriseur, der hat ihn gewaschen und gebürstet. Jetzt ist es viel besser. Du hast doch auch einen Hund mit langem Fell. Geh da mal hin, die machen das super. Ruf zurück, ich gebe dir die Adresse!","gender":"m","q":"Was war das Problem mit Markus' Hund?","opts":["Er hat stark gehaart.","Er war krank.","Er war zu dünn."],"correct":0},{"transcript":"Achtung Kunden: Bitte bringen Sie nur gesunde Tiere zu uns. Wenn Ihr Hund Flöhe oder eine Hautkrankheit hat, gehen Sie bitte zuerst zum Tierarzt. Kranke Tiere können wir nicht behandeln, das ist für die anderen Tiere gefährlich. Auch sehr ängstliche Tiere melden Sie bitte vorher an. Danke!","gender":"m","q":"Wohin soll man mit einem kranken Hund zuerst gehen?","opts":["Ins Tierheim.","Zum Tierfriseur.","Zum Tierarzt."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Hey, ich war mit meiner Katze beim Tierfriseur, weil ihr Fell ganz verfilzt war. Ich konnte es selbst nicht mehr kämmen. Jetzt ist sie wieder schön und glücklich. Ich wusste gar nicht, dass es das für Katzen auch gibt! Deine Katze hat doch auch langes Fell. Bis bald!","gender":"f","q":"Welches Tier hat Anna zum Tierfriseur gebracht?","opts":["Einen Hund.","Eine Katze.","Ein Kaninchen."],"correct":1},{"transcript":"Liebe Kunden: Wir bieten verschiedene Behandlungen an. Im Basis-Paket waschen und bürsten wir Ihren Hund. Im Komplett-Paket schneiden wir auch das Fell und die Krallen und reinigen die Ohren. Das Komplett-Paket dauert länger und kostet mehr. Fragen Sie nach, was für Ihr Tier passt!","gender":"f","q":"Was ist im Komplett-Paket zusätzlich dabei?","opts":["Fell und Krallen schneiden und Ohren reinigen.","Nur Waschen.","Nur Bürsten."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer braucht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Hunde kommen um drei. Welcher Hund bekommt heute was?"},{"speaker":"Lisa","gender":"f","text":"Ich habe die Karte hier. Fünf Hunde und keiner soll zu lange warten."},{"speaker":"Lukas","gender":"m","text":"Meiner war im Park ganz schmutzig. Ich lasse ihn heute waschen."},{"speaker":"Lisa","gender":"f","text":"Der schwarze braucht das auch. Putzt jemand heute auch die Zähne?"},{"speaker":"Lukas","gender":"m","text":"Zähne putzen wir heute nicht. Das machen wir an einem anderen Tag."},{"speaker":"Lisa","gender":"f","text":"Ich möchte einen Haarschnitt für meinen kleinen Hund."},{"speaker":"Lukas","gender":"m","text":"Die kurze Form steht ihm. Tom hat Angst, dass die Krallen zu lang sind."},{"speaker":"Lisa","gender":"f","text":"Tom lässt die Krallen schneiden. Sie sind zu lang für den Boden."},{"speaker":"Lukas","gender":"m","text":"Das kenne ich. Will jemand das Fell färben?"},{"speaker":"Lisa","gender":"f","text":"Fell färben wir nicht."},{"speaker":"Lukas","gender":"m","text":"Sara kommt mit einem Hund voller Blätter."},{"speaker":"Lisa","gender":"f","text":"Sara braucht Bürsten. Danach sieht das Haar wieder gut aus."},{"speaker":"Lukas","gender":"m","text":"Das dauert nicht lang. Was ist mit Tim und seinem Hund?"},{"speaker":"Lisa","gender":"f","text":"Tim lässt die Ohren reinigen. Der Hund schüttelt schon seit drei Tagen den Kopf."},{"speaker":"Lukas","gender":"m","text":"Das ist gut für ihn."},{"speaker":"Lisa","gender":"f","text":"Ich gebe unsere Karte jetzt an der Tür ab."}],"options":[{"letter":"a","text":"Ohren reinigen"},{"letter":"b","text":"Krallen schneiden"},{"letter":"c","text":"Zähne putzen"},{"letter":"d","text":"Baden mit Spezial-Shampoo"},{"letter":"e","text":"Fell färben"},{"letter":"f","text":"Bürsten"},{"letter":"g","text":"Waschen"},{"letter":"h","text":"Haarschnitt"},{"letter":"i","text":"Pfoten pflegen"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"h"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"a"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Was kostet das Waschen? 25 Euro, 40 Euro oder nur 15 Euro?"},{"speaker":"Tierfriseur","gender":"m","text":"Bei einem kleinen Hund 25 Euro. 15 Euro wäre zu wenig, 40 Euro ist der Preis für große Hunde."},{"speaker":"Kundin","gender":"f","text":"Und bei einem großen? 40 oder bleiben 25?"},{"speaker":"Tierfriseur","gender":"m","text":"Bei einem großen 40 Euro. Nicht 25 und nicht 15, ein großer Hund kostet 40."},{"speaker":"Kundin","gender":"f","text":"Verstehe, dann 40 Euro für meinen Großen. Danke."}],"q":"Was kostet das Waschen bei einem großen Hund?","opts":["25 Euro.","40 Euro.","15 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Mein Hund hat Angst vor dem Föhn. Geht es mit dem Handtuch oder an der Luft?"},{"speaker":"Tierfriseurin","gender":"f","text":"Kein Problem, wir trocknen mit dem Handtuch. Der Föhn muss nicht sein, an der Luft dauert es zu lang."},{"speaker":"Mann","gender":"m","text":"Dauert das nicht länger als mit dem Föhn?"},{"speaker":"Tierfriseurin","gender":"f","text":"Ein bisschen, aber der Hund bleibt ruhig. Also mit dem Handtuch, nicht mit dem Föhn und nicht an der Luft."},{"speaker":"Mann","gender":"m","text":"Perfekt, dann bitte mit dem Handtuch. Danke."}],"q":"Wie wird der Hund getrocknet?","opts":["Mit dem Föhn.","An der Luft.","Mit dem Handtuch."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Wie kurz soll das Fell werden? Der Hund ist nicht krank, und teurer soll es nicht sein."},{"speaker":"Tierfriseur","gender":"m","text":"Wie möchten Sie es? Weil er krank ist, oder weil es bald Winter wird?"},{"speaker":"Frau","gender":"f","text":"Nicht zu kurz, es ist bald Winter. Er ist nicht krank, und der Preis ist okay."},{"speaker":"Tierfriseur","gender":"m","text":"Gute Idee, dann nur etwas kürzen. Wegen des Winters, nicht Krankheit und nicht Preis."},{"speaker":"Frau","gender":"f","text":"Genau, wegen des Winters. Danke."}],"q":"Warum soll das Fell nicht zu kurz werden?","opts":["Der Hund ist krank.","Es ist bald Winter.","Es ist zu teuer."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Wie lange dauert die Behandlung? Soll ich warten, oder später abholen, oder helfen?"},{"speaker":"Tierfriseurin","gender":"f","text":"Etwa zwei Stunden. Warten müssen Sie nicht, und helfen auch nicht, das stört den Hund."},{"speaker":"Kunde","gender":"m","text":"Soll ich warten? Oder später abholen? Helfen darf ich nicht, oder?"},{"speaker":"Tierfriseurin","gender":"f","text":"Nein, holen Sie ihn später ab. Nicht warten und nicht helfen, später abholen ist am besten."},{"speaker":"Kunde","gender":"m","text":"Gut, dann hole ich ihn in zwei Stunden ab. Danke."}],"q":"Was soll der Kunde tun?","opts":["Warten.","Helfen.","Den Hund später abholen."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Brauche ich einen Termin? Nie, nur am Wochenende, oder am besten anrufen?"},{"speaker":"Tierfriseur","gender":"m","text":"Ja, am besten anrufen. Nie ohne Termin ist riskant, und nur am Wochenende stimmt nicht."},{"speaker":"Kundin","gender":"f","text":"Geht es auch ohne? Also nie anrufen, oder nur am Wochenende?"},{"speaker":"Tierfriseur","gender":"m","text":"Nur wenn gerade jemand absagt. Am besten anrufen, nicht ohne Anruf und nicht nur am Wochenende."},{"speaker":"Kundin","gender":"f","text":"Verstanden, ich rufe an. Danke."}],"q":"Braucht man einen Termin?","opts":["Ja, am besten anrufen.","Nein, nie.","Nur am Wochenende."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Kraus, einer Tierfriseurin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Kraus, was machen Sie genau bei der Arbeit?"},{"speaker":"Kraus","gender":"f","text":"Ich pflege das Fell von Hunden und Katzen. Ich wasche, schneide und bürste sie. Das ist der Hauptteil meiner Arbeit, jeden Tag."},{"speaker":"Reporter","gender":"m","text":"Ist die Arbeit mit den Tieren schwer? Kann man mit ängstlichen Tieren hektisch sein?"},{"speaker":"Kraus","gender":"f","text":"Manchmal, viele Tiere haben Angst. Ich brauche viel Geduld und Ruhe. Mit ängstlichen Tieren darf man nicht hektisch sein, sonst wird es schlimmer."},{"speaker":"Reporter","gender":"m","text":"Sollen die Besitzer das Fell selbst pflegen, zum Beispiel bürsten?"},{"speaker":"Kraus","gender":"f","text":"Das Bürsten ja. Aber das Schneiden ist schwer. Dafür kommen Sie besser zu mir. Das Bürsten sollen die Besitzer selbst machen, am besten jede Woche."},{"speaker":"Reporter","gender":"m","text":"Wollen die Leute manchmal seltsame Sachen, zum Beispiel den Hund bunt färben?"},{"speaker":"Kraus","gender":"f","text":"Ja, manche wollen den Hund bunt färben. Das mache ich nicht. Ein Tier ist kein Spielzeug. Ich färbe Hunde nicht gern bunt, das mag ich nicht."},{"speaker":"Reporter","gender":"m","text":"Was lieben Sie an Ihrem Beruf? Arbeiten Sie gern mit Tieren?"},{"speaker":"Kraus","gender":"f","text":"Ich liebe Tiere. Aus einem traurigen Tier wird ein glückliches. Ich arbeite sehr gern mit Tieren, das ist der schönste Teil."}],"items":[{"q":"Frau Kraus wäscht, schneidet und bürstet die Tiere.","correct":"ja"},{"q":"Sie sagt, man kann mit ängstlichen Tieren hektisch sein.","correct":"nein"},{"q":"Das Bürsten sollen die Besitzer selbst machen.","correct":"ja"},{"q":"Sie färbt Hunde gern bunt.","correct":"nein"},{"q":"Sie arbeitet gern mit Tieren.","correct":"ja"}]}]};
